Here is the solution. It uses a POSIX awk script to parse the file, collecting keys/values while tracking the last occurrence, and only emits output after the whole file has been validated.

```bash
#!/usr/bin/env bash
# solution.sh FILE
# Convert a dotenv file into shell-safe `export KEY='value'` lines.

set -u

if [ "$#" -ne 1 ]; then
  echo "usage: $0 FILE" >&2
  exit 2
fi

FILE=$1

awk '
function trim(s) {
  sub(/[ \t]+$/, "", s)
  return s
}
function sq(s,   out, i, c, n) {
  out = ""
  n = length(s)
  for (i = 1; i <= n; i++) {
    c = substr(s, i, 1)
    if (c == "\047") out = out "\047\\\047\047"
    else out = out c
  }
  return out
}
{
  line = $0
  # Strip trailing CR
  sub(/\r$/, "", line)
  # Skip blank / comment lines
  t = line
  sub(/^[ \t]+/, "", t)
  if (t == "" || substr(t, 1, 1) == "#") next

  # Optional leading export
  if (t ~ /^export[ \t]+/) {
    t = substr(t, 8)
    sub(/^[ \t]+/, "", t)
  }

  # KEY=VALUE
  if (t !~ /^[A-Za-z_][A-Za-z0-9_]*=/) {
    printf "%s:%d: invalid line\n", FILE, NR > "/dev/stderr"
    bad = 1
    exit 1
  }
  eq = index(t, "=")
  key = substr(t, 1, eq - 1)
  rest = substr(t, eq + 1)

  value = ""
  ok = 0

  if (substr(rest, 1, 1) == "\047") {
    # Single-quoted
    body = substr(rest, 2)
    # find closing quote
    j = index(body, "\047")
    if (j > 0) {
      value = substr(body, 1, j - 1)
      after = substr(body, j + 1)
      if (after ~ /^[ \t]*$/ || after ~ /^[ \t]+#/) ok = 1
    }
  } else if (substr(rest, 1, 1) == "\"") {
    # Double-quoted
    body = substr(rest, 2)
    n = length(body)
    out = ""
    i = 1
    closed = 0
    while (i <= n) {
      c = substr(body, i, 1)
      if (c == "\\") {
        nx = substr(body, i + 1, 1)
        if (nx == "n") { out = out "\n"; i += 2; continue }
        if (nx == "\"") { out = out "\""; i += 2; continue }
        if (nx == "\\") { out = out "\\"; i += 2; continue }
        out = out c
        i += 1
        continue
      }
      if (c == "\"") { closed = 1; i += 1; break }
      out = out c
      i += 1
    }
    if (closed) {
      after = substr(body, i)
      if (after ~ /^[ \t]*$/ || after ~ /^[ \t]+#/) { value = out; ok = 1 }
    }
  } else {
    # Unquoted: up to " #", trailing space/tab trimmed
    # find first occurrence of space followed by #
    pos = 0
    k = 1
    m = length(rest)
    while (k <= m) {
      if (substr(rest, k, 1) == " " && substr(rest, k + 1, 1) == "#") { pos = k; break }
      k++
    }
    if (pos > 0) value = substr(rest, 1, pos - 1)
    else value = rest
    value = trim(value)
    ok = 1
  }

  if (!ok) {
    printf "%s:%d: invalid line\n", FILE, NR > "/dev/stderr"
    bad = 1
    exit 1
  }

  # record last occurrence with later position
  if (!(key in seen)) {
    order[++count] = key
  }
  seen[key] = 1
  vals[key] = value
}
END {
  if (bad) exit 1
  for (i = 1; i <= count; i++) {
    k = order[i]
    printf "export %s=\047%s\047\n", k, sq(vals[k])
  }
}
' FILE="$FILE" "$FILE"
```

Key details:
- Lines are fully validated first; on the first invalid line the script writes the error and exits 1, and the `END` block suppresses all stdout when `bad` is set.
- Unquoted values stop at the first `" #"` (space then hash), so `a#b` keeps the hash, and trailing spaces/tabs are trimmed.
- Double-quoted values only translate `\n`, `\"`, `\\`; any other backslash escape is preserved literally (both the backslash and the following character).
- Repeated keys keep only the last value, but the key is printed at its last-occurrence position in input order.
- Values are emitted single-quoted with embedded `'` escaped as `'\''`.

